@RestController
public class StudentRecordsController {
    private final ErpStore store;private final AuthService auth;private final BusinessService business;private final ObjectMapper json;
    private static final List<String> FIELDS=Arrays.asList("studentNo","name","college","major","grade","className","enrollmentStatus","phone","email","counselorId");
    public StudentRecordsController(ErpStore store,AuthService auth,BusinessService business,ObjectMapper json){this.store=store;this.auth=auth;this.business=business;this.json=json;}
    private Map<String,Object>ok(Object data){return map("code",0,"data",data);}
    private Map<String,Object>profile(Map<String,Object>student){Map<String,Object>p;try{p=store.get("student_profile",s(student,"id"));}catch(ApiException e){p=map("id",s(student,"id"),"studentNo",s(student,"username"),"source","账号中心","updatedAt",s(student,"createdAt"),"enrollmentStatus","在籍","fieldSources",new LinkedHashMap<>());}p.put("name",s(student,"name"));p.put("className",s(student,"className"));if(s(p,"college").isEmpty())p.put("college",s(student,"college"));p.put("enabled",b(student,"enabled"));return p;}
    @PostMapping("/students/export") @Transactional
    public Map<String,Object> export(@RequestBody Map<String,Object> body,HttpServletRequest request) {
        Map<String,Object> actor=auth.require(request);Object raw=body.get("recordIds");
        if(!(raw instanceof List)||((List<?>)raw).isEmpty()||((List<?>)raw).size()>5000)throw new ApiException(400,"请选择1至5000名学生");
        Set<String> seen=new HashSet<>();List<Map<String,Object>> result=new ArrayList<>();
        for(Object value:(List<?>)raw) {
            if(!(value instanceof String)||!seen.add((String)value))throw new ApiException(400,"学生编号格式错误或重复");
            Map<String,Object> student=store.get("user",(String)value);business.ensure(auth.hasRole(student,"student")&&canRead(actor,student));
            Map<String,Object> visible=view(actor,profile(student)), row=new LinkedHashMap<>();
            for(String field:FIELDS)if(visible.containsKey(field))row.put(field,visible.get(field));
            result.add(row);
        }
        auth.audit(actor,"student.export","记录数 "+result.size());return ok(result);
    }
    private boolean canRead(Map<String,Object>a,Map<String,Object>u){return auth.hasRole(a,"admin")||auth.businessAccess(a,"student.read",u);}
    private boolean canEdit(Map<String,Object>a,Map<String,Object>u){return !s(a,"id").equals(s(u,"id"))&&(auth.hasRole(a,"admin")||auth.businessAccess(a,"student.edit",u));}
    private Map<String,Object>view(Map<String,Object>a,Map<String,Object>p){Map<String,Object>v=new LinkedHashMap<>(p);if(auth.hasRole(a,"admin")){v.remove("phone");v.remove("email");}return v;}
    @GetMapping("/students") public Map<String,Object>list(@RequestParam(defaultValue="")String q,@RequestParam(defaultValue="")String className,@RequestParam(defaultValue="")String grade,@RequestParam(defaultValue="")String status,HttpServletRequest request){Map<String,Object>a=auth.require(request);List<Map<String,Object>>out=new ArrayList<>();for(Map<String,Object>u:store.all("user"))if(auth.hasRole(u,"student")&&canRead(a,u)){Map<String,Object>p=profile(u);if((q.isEmpty()||(s(p,"studentNo")+s(p,"name")).contains(q))&&(className.isEmpty()||s(p,"className").equals(className))&&(grade.isEmpty()||s(p,"grade").equals(grade))&&(status.isEmpty()||s(p,"enrollmentStatus").equals(status)))out.add(view(a,p));}return ok(out);}
    @GetMapping("/students/{id}") public Map<String,Object>detail(@PathVariable String id,HttpServletRequest request){Map<String,Object>a=auth.require(request),u=store.get("user",id);business.ensure(auth.hasRole(u,"student")&&canRead(a,u));List<Map<String,Object>>changes=new ArrayList<>(),history=new ArrayList<>(),pending=new ArrayList<>();if(!auth.hasRole(a,"admin")){for(Map<String,Object>r:store.all("student_change"))if(s(r,"studentId").equals(id))changes.add(r);for(Map<String,Object>r:store.all("student_history"))if(s(r,"studentId").equals(id))history.add(r);for(String kind:Arrays.asList("task","request","collection"))for(Map<String,Object>r:store.all(kind))if((s(r,"userId").equals(id)||s(r,"assigneeId").equals(id))&&!Arrays.asList("completed","approved","cancelled","closed","rejected").contains(s(r,"status")))pending.add(map("kind",kind,"id",s(r,"id"),"status",s(r,"status")));}return ok(map("profile",view(a,profile(u)),"changes",changes,"history",history,"pending",pending,"handover",store.all("student_handover").stream().filter(r->s(r,"studentId").equals(id)).map(r->map("id",s(r,"id"),"createdAt",s(r,"createdAt"),"status",s(r,"status"))).collect(java.util.stream.Collectors.toList())));}
    @PostMapping("/students/{id}/change-requests") @Transactional public Map<String,Object>requestChange(@PathVariable String id,@RequestBody Map<String,Object>body,HttpServletRequest request){Map<String,Object>a=auth.require(request);auth.writeAllowed(a);if(!s(a,"id").equals(id)||!auth.hasRole(a,"student"))throw new ApiException(403,"仅学生本人可申请修改联系方式");Map<String,Object>values=object(body,"values");if(values.isEmpty()||!Arrays.asList("phone","email").containsAll(values.keySet()))throw new ApiException(400,"只允许申请修改手机号与邮箱");validate(values,false);for(Map<String,Object>c:store.all("student_change"))if(s(c,"studentId").equals(id)&&s(c,"status").equals("pending"))throw new ApiException(409,"已有待审核变更，请等待审核");Map<String,Object>c=map("id",id(),"studentId",id,"values",values,"before",profile(a),"reason",business.text(body,"reason",500,true),"status","pending","source","学生本人申请","createdAt",now());store.save("student_change",c);auth.audit(a,"student.change_requested","学生资料变更编号 "+s(c,"id"));return ok(c);}
    @PostMapping("/students/change-requests/{id}/decide") @Transactional public Map<String,Object>decideChange(@PathVariable String id,@RequestBody Map<String,Object>body,HttpServletRequest request){Map<String,Object>a=auth.require(request);auth.writeAllowed(a);Map<String,Object>c=store.get("student_change",id),u=store.get("user",s(c,"studentId"));business.ensure(!auth.hasRole(a,"admin")&&canEdit(a,u));if(!s(c,"status").equals("pending"))throw new ApiException(409,"申请已经处理");boolean approved=business.bool(body,"approved",false);String reason=business.text(body,"reason",500,true);if(approved)saveProfile(a,u,object(c,"values"),"学生申请经审核",reason);c.put("status",approved?"approved":"rejected");c.put("reviewerId",s(a,"id"));c.put("reviewedAt",now());c.put("reviewReason",reason);store.save("student_change",c);return ok(c);}
    @PutMapping("/students/{id}") @Transactional public Map<String,Object>update(@PathVariable String id,@RequestBody Map<String,Object>body,HttpServletRequest request){Map<String,Object>a=auth.require(request);auth.writeAllowed(a);Map<String,Object>u=store.get("user",id);business.ensure(auth.hasRole(u,"student")&&canEdit(a,u));Map<String,Object>values=object(body,"values");if(auth.hasRole(a,"admin")&&(values.containsKey("phone")||values.containsKey("email")))throw new ApiException(403,"账号管理员不能维护学生私密联系方式");validate(values,false);if(values.containsKey("className")&&!s(values,"className").equals(s(u,"className")))throw new ApiException(400,"转班请使用分工交接流程");return ok(view(a,saveProfile(a,u,values,"人工维护",business.text(body,"reason",500,true))));}
    @PostMapping("/students/{id}/transfer") @Transactional public Map<String,Object>transfer(@PathVariable String id,@RequestBody Map<String,Object>body,HttpServletRequest request){Map<String,Object>a=auth.require(request);auth.writeAllowed(a);Map<String,Object>u=store.get("user",id);business.ensure(auth.hasRole(u,"student")&&canEdit(a,u));String target=business.text(body,"className",100,true),counselor=business.text(body,"counselorId",80,true),reason=business.text(body,"reason",1000,true);Map<String,Object>next=store.get("user",counselor);if(!auth.hasRole(next,"counselor")||!auth.active(next)||!auth.classes(next).contains(target))throw new ApiException(400,"接替辅导员须有效且分管目标班级");Map<String,Object>before=profile(u);List<Map<String,Object>>items=new ArrayList<>();for(String kind:Arrays.asList("task","request","worklog"))for(Map<String,Object>r:store.all(kind))if((s(r,"assigneeId").equals(id)||s(r,"userId").equals(id)||s(r,"studentId").equals(id))&&!Arrays.asList("completed","closed","cancelled","rejected").contains(s(r,"status"))){items.add(map("kind",kind,"id",s(r,"id"),"sensitive",kind.equals("worklog"),"disposition",kind.equals("worklog")?"原保密权限保留，另行申请授权":"移交接替人"));if(kind.equals("task")){r.put("previousOwnerId",s(r,"ownerId"));r.put("ownerId",counselor);store.save(kind,r);}if(kind.equals("request")&&s(r,"type").equals("leave")){boolean reassigned=false;for(Map<String,Object>node:records(r,"approvalNodes"))if(Arrays.asList("waiting","pending").contains(s(node,"status"))){Map<String,Object>prior=store.get("user",s(node,"approverId"));if(auth.hasRole(prior,"counselor")&&auth.classes(prior).contains(s(before,"className"))){node.put("previousApproverId",s(prior,"id"));node.put("previousApproverName",s(prior,"name"));node.put("approverId",counselor);node.put("approverName",s(next,"name"));node.put("reassignedAt",now());node.put("reassignedBy",s(a,"id"));node.put("reassignmentReason",reason);reassigned=true;}}if(reassigned){r.put("version",((Number)r.getOrDefault("version",0)).intValue()+1);List<Map<String,Object>>history=records(r,"history");history.add(map("time",now(),"operatorId",s(a,"id"),"operator",s(a,"name"),"action","student_transfer","comment",reason));r.put("history",history);store.save(kind,r);}}}
        Map<String,Object>p=saveProfile(a,u,map("className",target,"counselorId",counselor),"分工交接",reason);store.revoke(id);Map<String,Object>h=map("id",id(),"studentId",id,"fromClass",s(before,"className"),"toClass",target,"counselorId",counselor,"items",items,"reason",reason,"status","pending_acceptance","createdAt",now(),"operatorId",s(a,"id"));store.save("student_handover",h);return ok(map("profile",view(a,p),"handover",h));}
    @GetMapping("/student-handovers") public Map<String,Object>handovers(HttpServletRequest request){Map<String,Object>a=auth.require(request);List<Map<String,Object>>out=new ArrayList<>();for(Map<String,Object>h:store.all("student_handover"))if(s(h,"counselorId").equals(s(a,"id"))||s(h,"operatorId").equals(s(a,"id"))||auth.hasRole(a,"admin"))out.add(h);return ok(out);}
    @PostMapping("/student-handovers/{id}/accept") @Transactional public Map<String,Object>accept(@PathVariable String id,@RequestBody Map<String,Object>body,HttpServletRequest request){Map<String,Object>a=auth.require(request);auth.writeAllowed(a);Map<String,Object>h=store.get("student_handover",id);if(!s(h,"counselorId").equals(s(a,"id")))throw new ApiException(403,"仅指定接替辅导员可确认交接");h.put("status","accepted");h.put("acceptedAt",now());h.put("note",business.text(body,"reason",500,true));store.save("student_handover",h);auth.audit(a,"student.handover_accept","交接编号 "+id);return ok(h);}
    @GetMapping("/student-filters") public Map<String,Object>filters(HttpServletRequest request){Map<String,Object>a=auth.require(request);return ok(store.all("student_filter").stream().filter(r->s(r,"ownerId").equals(s(a,"id"))).collect(java.util.stream.Collectors.toList()));}
    @PostMapping("/student-filters") @Transactional public Map<String,Object>saveFilter(@RequestBody Map<String,Object>body,HttpServletRequest request){Map<String,Object>a=auth.require(request);auth.writeAllowed(a);Map<String,Object>r=map("id",id(),"ownerId",s(a,"id"),"name",business.text(body,"name",80,true));for(String k:Arrays.asList("q","className","grade","status"))r.put(k,business.text(body,k,100,false));store.save("student_filter",r);return ok(r);}
    @PostMapping("/students/import/preview") @Transactional public Map<String,Object>preview(@RequestParam MultipartFile file,@RequestParam(defaultValue="{}")String mapping,HttpServletRequest request)throws Exception{Map<String,Object>a=auth.require(request);auth.writeAllowed(a);auth.roles(a,"admin","counselor");Map<String,String>columns;try{columns=json.readValue(mapping,new TypeReference<Map<String,String>>(){});}catch(Exception e){throw new ApiException(400,"字段映射格式不正确");}List<Map<String,Object>>rows=TabularImport.parse(file),result=new ArrayList<>();Set<String>seen=new HashSet<>();int index=1;Map<String,Map<String,Object>>existing=new HashMap<>();for(Map<String,Object>u:store.all("user"))if(auth.hasRole(u,"student"))existing.put(s(profile(u),"studentNo"),u);
        Set<String>knownClasses=new HashSet<>(),usernames=new HashSet<>(),pendingChanges=new HashSet<>();for(Map<String,Object>o:store.all("organization"))if(s(o,"type").equals("class")&&b(o,"active"))knownClasses.add(s(o,"name"));for(Map<String,Object>u:store.all("user")){knownClasses.addAll(auth.classes(u));usernames.add(s(u,"username").toLowerCase(Locale.ROOT));}for(Map<String,Object>c:store.all("student_change"))if(s(c,"status").equals("pending"))pendingChanges.add(s(c,"studentId"));for(Map<String,Object>raw:rows){Map<String,Object>v=new LinkedHashMap<>();for(String k:FIELDS){String column=columns.getOrDefault(k,k);if(raw.containsKey(column))v.put(k,String.valueOf(raw.get(column)));}Map<String,Object>row=map("row",++index,"values",v,"action","error","error","");try{validate(v,true);if(!seen.add(s(v,"studentNo")))throw new ApiException(400,"文件内学号重复");Map<String,Object>u=existing.get(s(v,"studentNo"));if(u!=null&&!canEdit(a,u))throw new ApiException(403,"学生不在授权范围");if(!auth.hasRole(a,"admin")&&!auth.classes(a).contains(s(v,"className")))throw new ApiException(403,"目标班级不在当前分管范围");if(!knownClasses.contains(s(v,"className")))throw new ApiException(400,"班级不存在，请先维护组织");if(u!=null){if(pendingChanges.contains(s(u,"id")))throw new ApiException(409,"学生存在待审核资料变更，禁止导入覆盖");if(!s(v,"className").equals(s(u,"className")))throw new ApiException(409,"转班须走交接流程");row.put("studentId",s(u,"id"));row.put("baseUpdatedAt",s(profile(u),"updatedAt"));row.put("action",v.entrySet().stream().allMatch(e->String.valueOf(e.getValue()).equals(s(profile(u),e.getKey())))?"skip":"update");}else{if(!s(v,"studentNo").matches("[A-Za-z0-9_.@-]{3,64}"))throw new ApiException(400,"学号用于初始账号，须3至64位字母数字或_.@-");if(usernames.contains(s(v,"studentNo").toLowerCase(Locale.ROOT)))throw new ApiException(409,"学号与其他账号冲突");row.put("action","create");}}catch(ApiException e){row.put("error",e.getMessage());}result.add(row);}
        Map<String,Object>batch=map("id",id(),"ownerId",s(a,"id"),"rows",result,"createdAt",now(),"expiresAt",Instant.now().plusSeconds(3600).toString(),"committed",false);store.save("student_import",batch);auth.audit(a,"student.import_preview","预检编号 "+s(batch,"id")+"；行数 "+rows.size());return ok(importView(batch));}
    @PostMapping("/students/import/{id}/commit") @Transactional public Map<String,Object>commit(@PathVariable String id,@RequestBody Map<String,Object>body,HttpServletRequest request){Map<String,Object>a=auth.require(request);auth.writeAllowed(a);auth.roles(a,"admin","counselor");Map<String,Object>batch=store.get("student_import",id);if(!s(batch,"ownerId").equals(s(a,"id"))||auth.expired(s(batch,"expiresAt")))throw new ApiException(403,"预检不属于本人或已过期");if(b(batch,"committed"))return ok(importView(batch));List<Map<String,Object>>rows=records(batch,"rows");if(!b(body,"validOnly")&&rows.stream().anyMatch(r->!s(r,"error").isEmpty()))throw new ApiException(409,"预检存在错误，请修正或明确选择仅导入有效行");String reason=business.text(body,"reason",500,true);Set<String>currentNames=new HashSet<>(),currentStudentNumbers=new HashSet<>(),pendingStudentIds=new HashSet<>();for(Map<String,Object>existing:store.all("user")){currentNames.add(s(existing,"username").toLowerCase(Locale.ROOT));if(auth.hasRole(existing,"student"))currentStudentNumbers.add(s(profile(existing),"studentNo"));}for(Map<String,Object>change:store.all("student_change"))if(s(change,"status").equals("pending"))pendingStudentIds.add(s(change,"studentId"));for(Map<String,Object>r:rows){if(!s(r,"error").isEmpty()||s(r,"action").equals("skip"))continue;Map<String,Object>v=object(r,"values"),u;if(s(r,"action").equals("create")){if(!currentNames.add(s(v,"studentNo").toLowerCase(Locale.ROOT))||!currentStudentNumbers.add(s(v,"studentNo")))throw new ApiException(409,"预检后账号或学号冲突，请重新预检");u=map("id",id(),"username",s(v,"studentNo"),"name",s(v,"name"),"className",s(v,"className"),"role","student","enabled",false,"theme","blue","mustChangePassword",true,"passwordHash","","createdAt",now());store.save("user",u);}else{u=store.get("user",s(r,"studentId"));business.ensure(canEdit(a,u));if(!s(profile(u),"updatedAt").equals(s(r,"baseUpdatedAt")))throw new ApiException(409,"预检后档案已变更，请重新预检");if(pendingStudentIds.contains(s(u,"id")))throw new ApiException(409,"出现待审核资料变更，请先处理");}if(!auth.hasRole(a,"admin")&&!auth.classes(a).contains(s(v,"className")))throw new ApiException(403,"导入期间分管范围已变更");saveProfile(a,u,v,"表格导入 "+id,reason);}batch.put("committed",true);batch.put("committedAt",now());store.save("student_import",batch);auth.audit(a,"student.import_commit","导入编号 "+id);return ok(importView(batch));}
    private Map<String,Object>importView(Map<String,Object>b){List<Map<String,Object>>rows=records(b,"rows");Map<String,Object>counts=map("create",0L,"update",0L,"skip",0L,"error",0L);for(Map<String,Object>r:rows){String k=s(r,"error").isEmpty()?s(r,"action"):"error";counts.put(k,((Number)counts.get(k)).longValue()+1);}return map("id",s(b,"id"),"rows",rows,"counts",counts,"committed",b(b,"committed"));}
    private void validate(Map<String,Object>v,boolean required){if(!FIELDS.containsAll(v.keySet()))throw new ApiException(400,"包含不允许维护的字段");for(Map.Entry<String,Object>e:v.entrySet()){if(!(e.getValue() instanceof String)||String.valueOf(e.getValue()).length()>200)throw new ApiException(400,e.getKey()+"字段格式或长度不正确");}for(String k:Arrays.asList("studentNo","name","college","major","grade","className","enrollmentStatus"))if(required||v.containsKey(k))business.text(v,k,100,true);if(v.containsKey("phone")&&!s(v,"phone").isEmpty()&&!s(v,"phone").matches("[+0-9 ()-]{6,25}"))throw new ApiException(400,"手机号格式不正确");if(v.containsKey("email")&&!s(v,"email").isEmpty()&&!s(v,"email").matches("[^\\s@]+@[^\\s@]+\\.[^\\s@]+"))throw new ApiException(400,"邮箱格式不正确");if(v.containsKey("enrollmentStatus")&&!Arrays.asList("在籍","休学","毕业","退学","归档").contains(s(v,"enrollmentStatus")))throw new ApiException(400,"学籍状态无效");}
    @SuppressWarnings("unchecked")private Map<String,Object>saveProfile(Map<String,Object>a,Map<String,Object>u,Map<String,Object>values,String source,String reason){Map<String,Object>before=profile(u),p=new LinkedHashMap<>(before);if(values.containsKey("studentNo")&&!s(values,"studentNo").equals(s(before,"studentNo")))for(Map<String,Object>other:store.all("user"))if(auth.hasRole(other,"student")&&!s(other,"id").equals(s(u,"id"))&&s(profile(other),"studentNo").equals(s(values,"studentNo")))throw new ApiException(409,"学号已存在");Map<String,Object>sources=new LinkedHashMap<>((Map<String,Object>)p.getOrDefault("fieldSources",new LinkedHashMap<>()));for(Map.Entry<String,Object>e:values.entrySet()){p.put(e.getKey(),e.getValue());sources.put(e.getKey(),map("source",source,"updatedAt",now()));}p.put("fieldSources",sources);p.put("updatedAt",now());p.put("source",source);store.save("student_profile",p);for(String k:Arrays.asList("name","className","college"))if(values.containsKey(k))u.put(k,values.get(k));u.put("updatedAt",now());store.save("user",u);store.save("student_history",map("id",id(),"studentId",s(u,"id"),"before",before,"after",p,"source",source,"reason",reason,"operatorId",s(a,"id"),"createdAt",now()));auth.audit(a,"student.update","主档 "+s(u,"id")+"；字段 "+String.join(",",values.keySet()));return p;}
}
